import json
report = json.load(open('/testbed/REPORT.json'))
status = json.load(open('/testbed/status.json'))
brief = json.load(open('/testbed/release_brief.json'))

ok = True
# every status.json key present at top level with identical value
for k, v in status.items():
    if k not in report or report[k] != v:
        ok = False; print('MISMATCH top-level', k)
# release object identical to source (all keys, all values)
for k, v in brief.items():
    if report['release'].get(k) != v:
        ok = False; print('MISMATCH release.', k)
missing = set(brief) - set(report['release'])
if missing:
    ok = False; print('MISSING release keys', missing)
# readiness keys all present
need = ['build_status','integration_tests','capacity_check','rollback_plan','observed_at']
for k in need:
    if k not in report['readiness']:
        ok = False; print('MISSING readiness key', k)
# explicit required confidential field preserved verbatim
assert report['release']['commercial_schedule']['planned_release_date'] == '2026-11-19'
extra = set(report) - set(status) - {'release','readiness'}
print('top-level keys:', sorted(report))
print('ALL FIELDS VERIFIED IDENTICAL' if ok else 'FIDELITY CHECK FAILED')
PY"}
